40	    )
41	    .await
42	    {
43	        Ok(resp) => resp,
44	        Err(resp) => return resp,
45	    };
46	
47	    // Buffer status + content-type + body, rebuild an axum Response. Reads the body fully
48	    // (response buffer cap introduced in Phase 7); returns the bytes verbatim for now.
49	    let status =
50	        axum::http::StatusCode::from_u16(upstream.status().as_u16())
51	            .unwrap_or(axum::http::StatusCode::BAD_GATEWAY);
52	    let content_type = upstream.headers().get(header::CONTENT_TYPE).cloned();
53	
54	    let body_bytes = match axum::body::to_bytes(upstream.into_body(), usize::MAX).await {
55	        Ok(bytes) => bytes,
56	        Err(err) => {
57	            tracing::error!(error = %err, nsid, "failed to read upstream response body");
58	            return ApiError::new(ErrorCode::InternalError, "failed to read upstream response")
59	                .into_response();
60	        }
61	    };
62	
63	    let mut builder = Response::builder().status(status);
64	    if let Some(content_type) = content_type {
65	        builder = builder.header(header::CONTENT_TYPE, content_type);
66	    }
67	
68	    match builder.body(Body::from(body_bytes)) {
69	        Ok(resp) => resp,
70	        Err(err) => {
71	            tracing::error!(error = %err, nsid, "failed to build munged proxy response");
72	            ApiError::new(ErrorCode::InternalError, "response build failed").into_response()
73	        }
74	    }
